insert into public.site_content(key,value) values ('seo','{"title": "Akhtar Shaikh — Frontend & AI Automation Developer", "description": "Akhtar Shaikh — Full Stack, React / React Native and AI automation developer in Chh. Sambhajinagar, India. Open to remote roles and freelance work.", "og_image": "/og.png"}'::jsonb),('hero','{"first": "Akhtar", "last": "Shaikh", "badge": "Open to remote roles & freelance work", "title": "Frontend & AI Automation Developer", "pitch": "React / React Native apps, Node backends, Docker on AWS, and local-LLM agents. Open to remote full-stack, backend and AI automation roles — and freelance projects.", "meta": "Chh. Sambhajinagar, India · Since 2019", "cta_primary": "See work", "cta_secondary": "Resume ↓"}'::jsonb),('about','{"kicker": "About", "text": "I build responsive web and mobile apps with React and React Native — professionally since 2020, freelancing since 2019. Today I''m a Full Stack Developer at Just Logic Software, and outside of work I build offline AI workspaces and multi-agent systems with Ollama, OpenRouter and Hermes, shipped with Docker on AWS and VPS."}'::jsonb),('sections','{"skills": "What I\nwork with", "experience": "Where I''ve\nbeen building", "work": "Things\nI''ve built", "work_sub": "Personal and freelance projects from my resume. Scroll →", "repos": "On GitHub", "contact": "Let''s work\ntogether"}'::jsonb),('marquee','{"primary": ["React", "React Native", "TypeScript", "JavaScript", "Node.js", "MongoDB", "MERN", "Tailwind", "Python", "FastAPI", "REST APIs"], "secondary": ["AWS EC2", "AWS S3", "Docker", "Docker Compose", "Linux", "CI/CD", "Git", "Vercel", "Supabase", "Ollama", "OpenRouter", "Hermes", "Discord bots", "Telegram bots", "Figma"]}'::jsonb),('skills','[{"group": "Languages & Frontend", "items": ["JavaScript (ES6+)", "TypeScript", "Python", "React.js", "React Native", "HTML5", "CSS3", "Tailwind"]}, {"group": "Backend & APIs", "items": ["Node.js", "FastAPI / Flask (basics)", "RESTful APIs", "MongoDB", "MERN"]}, {"group": "DevOps & Cloud", "items": ["AWS (EC2, S3)", "Docker & Compose", "Linux administration", "Git / GitHub", "CI/CD", "Vercel", "Supabase"]}, {"group": "AI & Automation", "items": ["Local LLM deployment", "Ollama", "OpenRouter", "Hermes", "AI agent frameworks", "Discord / Telegram bots"]}]'::jsonb),('experience','[{"role": "Full Stack Developer", "org": "Just Logic Software Pvt Ltd", "where": "Chh. Sambhajinagar, MH", "when": "Jun 2021 — Present", "points": ["Develop and maintain web and cross-platform mobile apps with React, React Native and the MERN stack.", "Frontend architecture, API integrations and performance improvements.", "Cloud deployments on AWS EC2 and Docker containerization for dev and production.", "Backend integrations and automation workflows for business clients."]}, {"role": "Freelance Developer", "org": "Self-Employed", "where": "Remote", "when": "Jun 2019 — Present", "points": ["Web and mobile projects for clients — React / React Native frontends with backend integrations.", "Custom automation workflows on third-party APIs and foundational CI/CD pipelines to streamline releases.", "Deployments on AWS, Docker and VPS; AI-powered automation and LLM workflows."]}, {"role": "React Native Developer", "org": "Subtle Solution Pvt Ltd", "where": "Chh. Sambhajinagar, MH", "when": "Feb 2020 — May 2021", "points": ["Cross-platform mobile apps in React Native, focused on performance and UX.", "Responsive React.js interfaces as clean, component-based code.", "Shipped features and resolved production issues with cross-functional teams."]}]'::jsonb),('contact','{"email": "akhtarshaikh0299@gmail.com", "phone": "+91 79722 72861", "location": "Remote / Chh. Sambhajinagar, India", "socials": [{"label": "LinkedIn", "url": "https://www.linkedin.com/in/akhtarshaikh-mac/"}, {"label": "GitHub", "url": "https://github.com/akhtar-mac"}]}'::jsonb),('resume','{"url": "/Akhtar_Shaikh_Resume.pdf", "label": "Resume (PDF) ↓"}'::jsonb) on conflict (key) do update set value=excluded.value;
insert into public.projects(title,tag,kind,language,description,hue,repo_url,cover_url,tech,sort_order,featured) values ('Offline AI Development Workspace','Personal project','build',null,'A portable, fully offline AI platform: a browser dashboard for coding, terminal execution and AI assistance. Local inference via Ollama with model selection based on available system resources, persistent memory, multi-user profiles, and Windows / Linux / macOS support — runnable from external storage.',245,null,'/covers/cover-1.webp',array['React','Node.js','Python','Ollama','Docker','Linux','OpenRouter']::text[],0,true);
insert into public.projects(title,tag,kind,language,description,hue,repo_url,cover_url,tech,sort_order,featured) values ('AI Agent & Business Automation Platform','Personal project','build',null,'A multi-agent system with a manager-worker architecture delegating coding help, research, customer support and operations. Agents run across Discord, Telegram and web with persistent sessions, local or cloud LLM backends, and Dockerised services on a VPS.',280,null,'/covers/cover-2.webp',array['Python','OpenRouter','Ollama','Discord','Telegram','Hugging Face','Docker','Hermes']::text[],1,true);
insert into public.projects(title,tag,kind,language,description,hue,repo_url,cover_url,tech,sort_order,featured) values ('Containerised Deployment Environments','Freelance project','build',null,'Reusable Docker images and Compose configurations that standardise local and production multi-service environments across client projects.',200,null,'/covers/cover-3.webp',array['Docker','Docker Compose','Linux','AWS EC2']::text[],2,true);
